<?php
declare(strict_types=1);
const SHIFTS = [['id'=>'day_first','name'=>'Ca 1','start'=>9,'end'=>14],['id'=>'day_second','name'=>'Ca 2','start'=>14,'end'=>19]];
const PROFILE_FIELDS=['phone','department','job_title','start_date','birth_date','address','bank_name','bank_account','bank_holder','notes'];
const CLIENT_VERSION='2026-10-20-photo2';
function fail(string $message,int $status=400): never {throw new HttpError($message,$status);}
class HttpError extends RuntimeException {public function __construct(string $message,public int $status=400){parent::__construct($message);}}
function text_length(string $text): int {return preg_match_all('/./us',$text)?:0;}
function now_ms(): int {return (int)floor(microtime(true)*1000);}
function local_day(int $time): string {return gmdate('Y-m-d',(int)floor($time/1000)+7*3600);}
function day_time(string $day,int $hour=0): int {return strtotime($day.'T00:00:00+07:00')*1000+$hour*3600000;}
function valid_day(mixed $day): string {if(!is_string($day)||!preg_match('/^(?:19|20)\d{2}-\d{2}-\d{2}$/D',$day)||date('Y-m-d',strtotime($day.'T00:00:00Z'))!==$day)fail('Ngày không hợp lệ.');return $day;}
function valid_month(mixed $month): string {if(!is_string($month)||!preg_match('/^20\d{2}-(0[1-9]|1[0-2])$/D',$month))fail('Tháng không hợp lệ.');return $month;}
function bounds(string $day,?string $id): ?array {foreach([...SHIFTS,['id'=>'morning','start'=>9,'end'=>12],['id'=>'midday','start'=>12,'end'=>15],['id'=>'afternoon','start'=>15,'end'=>18]] as $s)if($s['id']===$id)return ['start'=>day_time($day,$s['start']),'end'=>day_time($day,$s['end'])];return null;}
function pairs(array $events): array {usort($events,fn($a,$b)=>[$a['time'],$a['id']??0]<=>[$b['time'],$b['id']??0]);$pending=[];$pairs=[];foreach($events as $e){$key=empty($e['shift'])?'legacy':($e['work_date']??'').':'.$e['shift'];if($e['type']==='in')$pending[$key]=$e;elseif(isset($pending[$key])){$entry=$pending[$key];unset($pending[$key]);$w=empty($entry['shift'])?null:bounds($entry['work_date']??local_day($entry['time']),$entry['shift']);$pairs[]=['entry'=>$entry,'exit'=>$e,'start'=>max($entry['time'],$w['start']??$entry['time']),'end'=>min($e['time'],$w['end']??$e['time'])];}}return ['pairs'=>$pairs,'pending'=>array_values($pending)];}
function attendance_decision(array $events,mixed $shift,int $now,bool $late=false): array {$day=local_day($now);$pending=pairs($events)['pending'];$ot=null;foreach($pending as $e)if($e['shift']==='ot'){$ot=$e;break;}if($shift==='ot'){if($ot)return ['type'=>'out','workDate'=>$ot['work_date']];if((int)gmdate('G',(int)floor($now/1000)+25200)<19)fail('Chỉ được bắt đầu OT từ 19:00. OT đang mở có thể kết thúc sau nửa đêm.',409);foreach($pending as $e)if($e['shift']!=='ot'&&$e['work_date']===$day)fail('Hãy chấm ra ca chính trước khi bắt đầu OT.',409);return ['type'=>'in','workDate'=>$day];}if($ot)fail('Hãy kết thúc lượt OT đang mở trước khi chấm ca chính.',409);if(!in_array($shift,['day_first','day_second'],true))fail('Ca làm không hợp lệ.');$w=bounds($day,$shift);$own=array_values(array_filter($events,fn($e)=>$e['shift']===$shift&&$e['work_date']===$day));foreach($own as $e)if($e['type']==='out')fail('Bạn đã hoàn tất ca này hôm nay.',409);foreach($own as $e)if($e['type']==='in'){if(!$late&&$now>$w['end']+1800000)fail('Đã quá hạn checkout '.($shift==='day_first'?'14:30':'19:30').'. Hãy gửi yêu cầu bổ sung công.',409);return ['type'=>'out','workDate'=>$day];}if($now<$w['start']||$now>=$w['end'])fail('Chỉ được chấm vào trong khung giờ của ca đã chọn.',409);return ['type'=>'in','workDate'=>$day];}
function has_ot(array $events,int $time,int $now): bool {$p=pairs($events);foreach($p['pairs'] as $s)if($s['entry']['shift']==='ot'&&$time>=$s['start']&&$time<=$s['end'])return true;foreach($p['pending'] as $s)if($s['shift']==='ot'&&$time>=$s['time']&&$time<=$now)return true;return false;}
function summary(array $events,string $month,int $salary,array $commissions): array {$start=day_time($month.'-01');$end=strtotime($month.'-01T00:00:00+07:00 +1 month')*1000;$p=pairs($events);$ms=0;$ot=0;$sessions=0;$credit=[];$days=[];$legacy=0;foreach($p['pairs'] as $s){$a=max($start,$s['start']);$b=min($end,$s['end']);if($s['start']>=$start&&$s['start']<$end&&!in_array($s['entry']['shift'],['day_first','day_second','ot'],true))$legacy++;if($b<=$a)continue;if($s['entry']['shift']==='ot'){$ot+=$b-$a;$sessions++;continue;}$ms+=$b-$a;if(in_array($s['entry']['shift'],['day_first','day_second'],true))$credit[$s['entry']['work_date'].':'.$s['entry']['shift']]=true;for($t=$a;$t<$b;){$d=local_day($t);$days[$d]=true;$t=min($b,day_time(gmdate('Y-m-d',strtotime($d.'T00:00:00Z')+86400)));}}$incomplete=0;$otOpen=0;foreach($p['pending'] as $s){if($s['shift']==='ot'&&$s['time']<$end)$otOpen++;elseif($s['shift']!=='ot'&&$s['time']>=$start&&$s['time']<$end)$incomplete++;}$regular=0;$customersOT=0;$commission=0;foreach($commissions as $c)if($c['served_at']>=$start&&$c['served_at']<$end){if($c['rate']===15000)$regular+=$c['customers'];if($c['rate']===30000)$customersOT+=$c['customers'];$commission+=$c['rate']*$c['customers'];}$workdays=count($credit)/2;$base=(int)round($salary/31*$workdays);return ['otHours'=>round($ot/3600000,2),'otSessions'=>$sessions,'otIncomplete'=>$otOpen,'completedShifts'=>count($credit),'days'=>count($days),'hours'=>round($ms/3600000,2),'workdays'=>$workdays,'monthly_salary'=>$salary,'base_salary'=>$base,'regular_customers'=>$regular,'ot_customers'=>$customersOT,'commission'=>$commission,'salary'=>$base+$commission,'incomplete'=>$incomplete,'legacyShifts'=>$legacy];}
function visible_summary(array $user,array $row): array {if($user['role']!=='employee')return $row;return array_intersect_key($row,array_flip(['days','hours','workdays','completedShifts','incomplete','otHours','otSessions','otIncomplete','legacyShifts']));}
function authorize_edit(array $actor,?array $target,array $change=[]): void {if(!in_array($actor['role'],['admin','manager'],true))fail('Bạn không có quyền quản lý nhân viên.',403);if($actor['role']==='manager'&&(($target&&$target['role']!=='employee')||isset($change['role'])&&$change['role']!=='employee'))fail('Quản lý chỉ được quản lý tài khoản Nhân viên.',403);if($target&&$target['id']===$actor['id']&&((isset($change['role'])&&$change['role']!==$actor['role'])||($change['status']??'')==='inactive'||($change['archived']??false)))fail('Bạn không thể tự hạ quyền, khóa hoặc xóa tài khoản đang sử dụng.');}
function validate_employee(array $b,bool $create=false): array {foreach(['name','email'] as $f)if(!is_string($b[$f]??null))fail('Nhập họ tên và email.');$b['name']=trim($b['name']);$b['email']=strtolower(trim($b['email']));if(!$b['name']||!preg_match('//u',$b['name'])||text_length($b['name'])>80||!filter_var($b['email'],FILTER_VALIDATE_EMAIL)||strlen($b['email'])>254)fail('Họ tên hoặc email không hợp lệ.');if(!in_array($b['role']??'', ['admin','manager','employee'],true)||!in_array($b['status']??'',['active','probation','inactive'],true))fail('Vai trò/trạng thái không hợp lệ.');if(!is_int($b['monthly_salary']??null)||$b['monthly_salary']<0||$b['monthly_salary']>1000000000)fail('Lương cứng không hợp lệ.');if($create||!empty($b['password']))if(!is_string($b['password']??null)||strlen($b['password'])<10||strlen($b['password'])>128)fail('Mật khẩu cần từ 10–128 ký tự.');foreach(PROFILE_FIELDS as $f){$b[$f]=$b[$f]??'';if(!is_string($b[$f])||!preg_match('//u',$b[$f])||text_length($b[$f])>($f==='notes'?2000:($f==='address'?500:150)))fail('Thông tin hồ sơ quá dài.');$b[$f]=trim($b[$f]);}if($b['phone']&&!preg_match('/^[+\d\s().-]{7,25}$/D',$b['phone']))fail('Số điện thoại không hợp lệ.');if($b['bank_account']&&!preg_match('/^[A-Za-z0-9 -]{3,50}$/D',$b['bank_account']))fail('Số tài khoản không hợp lệ.');foreach(['start_date','birth_date'] as $f)if($b[$f])valid_day($b[$f]);return $b;}
function position_distance(mixed $p,?array $studio,int $now): int {if(!$studio)fail('Quản lý chưa cài đặt vị trí studio.');foreach(['latitude','longitude','accuracy','timestamp'] as $f)if(!isset($p[$f])||!is_numeric($p[$f])||!is_finite((float)$p[$f]))fail('Dữ liệu vị trí không hợp lệ.');if(abs($p['latitude'])>90||abs($p['longitude'])>180||$p['accuracy']<0)fail('Dữ liệu vị trí không hợp lệ.');if($now-$p['timestamp']>60000||$p['timestamp']>$now+10000)fail('Vị trí đã cũ. Vui lòng lấy lại vị trí.');$allowed=min(100,$studio['radius']);if($p['accuracy']>$allowed)fail('GPS chưa đủ chính xác: sai số khoảng '.ceil($p['accuracy']).' m, mức cho phép '.$allowed.' m. Hãy bật vị trí chính xác rồi thử lại.');$lat=deg2rad($p['latitude']-$studio['latitude']);$lon=deg2rad($p['longitude']-$studio['longitude']);$h=sin($lat/2)**2+cos(deg2rad($studio['latitude']))*cos(deg2rad($p['latitude']))*sin($lon/2)**2;$distance=6371000*2*atan2(sqrt($h),sqrt(max(0,1-$h)));if($distance>$studio['radius'])fail('Bạn cách studio '.round($distance).' m, ngoài bán kính '.$studio['radius'].' m.');return (int)round($distance);}
function normalize_photo(mixed $value): string {if(!is_string($value)||!$value)fail('Chưa nhận được ảnh chấm công. Hãy mở camera và nhấn Dùng ảnh & chấm công.');if(strlen($value)>350000)fail('Ảnh chấm công vượt 250 KB. Hãy tải lại trang rồi chụp lại.');if(!preg_match('~^data:image/jpeg;base64,([A-Za-z0-9+/]+={0,2})$~D',$value,$m))fail('Ảnh gửi lên không đúng định dạng JPEG.');$bytes=base64_decode($m[1],true);if($bytes===false||strlen($bytes)>250000)fail('Ảnh quá lớn hoặc không hợp lệ.');$size=@getimagesizefromstring($bytes);if(!$size||$size[2]!==IMAGETYPE_JPEG||min($size[0],$size[1])<160||max($size[0],$size[1])>1280||$size[0]*$size[1]>2000000)fail('Ảnh không hợp lệ hoặc quá nhỏ. Hãy chụp lại bằng camera.');$image=@imagecreatefromstring($bytes);if(!$image)fail('Không đọc được ảnh camera.');ob_start();imagejpeg($image,null,80);$clean=ob_get_clean();imagedestroy($image);return $clean;}
